import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

// Response shapes from openapi.json, trimmed to the fields this scenario asserts.
type VendorBody = { id: string; status: string };
type DocumentBody = { id: string; kind: string; status: string };
type ExtractionBody = { id: string; document_id: string; kind: string; status: string };
type QueueItem = {
  vendor_id: string;
  extractions: ExtractionBody[];
};

const PDF = Buffer.from("%PDF-1.4\n% LIF-05 fixture\n%%EOF\n");

/** Creates a vendor with a name and contact email unique to this test run. */
async function createVendor(member: APIRequestContext): Promise<VendorBody> {
  const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const response = await member.post("/api/vendors", {
    data: {
      name: `LIF-05 Vendor ${suffix}`,
      category: "services",
      contact_email: `lif05-${suffix}@example.test`,
    },
  });
  return expectStatus<VendorBody>(response, 201);
}

/** Uploads one document of the given kind and returns its metadata. */
async function uploadDocument(
  member: APIRequestContext,
  vendorId: string,
  kind: "w9" | "insurance_certificate" | "contract",
): Promise<DocumentBody> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: PDF },
    },
  });
  return expectStatus<DocumentBody>(response, 201);
}

/** Waits until a document has been extracted, then returns its extraction. */
async function waitForExtraction(member: APIRequestContext, documentId: string): Promise<ExtractionBody> {
  await expect
    .poll(
      async () => {
        const doc = await expectStatus<DocumentBody>(await member.get(`/api/documents/${documentId}`), 200);
        return doc.status;
      },
      { timeout: 60_000, intervals: [500, 1_000, 2_000] },
    )
    .toBe("extracted");

  return expectStatus<ExtractionBody>(await member.get(`/api/documents/${documentId}/extraction`), 200);
}

/** Records a reviewer decision on an extraction. */
async function decide(
  reviewer: APIRequestContext,
  extractionId: string,
  decision: "approve" | "reject",
): Promise<ExtractionBody> {
  const response = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision },
  });
  return expectStatus<ExtractionBody>(response, 200);
}

test(
  "After a replacement, only the new document waits for review",
  { tag: "@LIF-05" },
  async ({ apiAs }) => {
    // Arrange: a vendor with insurance and contract approved and a w9 rejected.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const vendor = await createVendor(member);

    const insuranceDoc = await uploadDocument(member, vendor.id, "insurance_certificate");
    const contractDoc = await uploadDocument(member, vendor.id, "contract");
    const originalW9Doc = await uploadDocument(member, vendor.id, "w9");

    const insuranceExtraction = await waitForExtraction(member, insuranceDoc.id);
    const contractExtraction = await waitForExtraction(member, contractDoc.id);
    const originalW9Extraction = await waitForExtraction(member, originalW9Doc.id);

    await decide(reviewer, insuranceExtraction.id, "approve");
    await decide(reviewer, contractExtraction.id, "approve");
    await decide(reviewer, originalW9Extraction.id, "reject");

    const initialSubmit = await expectStatus<VendorBody>(
      await member.post(`/api/vendors/${vendor.id}/submit`),
      200,
    );
    expect(initialSubmit.status).toBe("in_review");

    // Act: replace the w9, wait for extraction, and submit again.
    const newW9Doc = await uploadDocument(member, vendor.id, "w9");
    const newW9Extraction = await waitForExtraction(member, newW9Doc.id);
    expect(newW9Extraction.status).toBe("pending_review");

    const resubmitted = await expectStatus<VendorBody>(
      await member.post(`/api/vendors/${vendor.id}/submit`),
      200,
    );

    // Assert: vendor is back in review.
    expect(resubmitted.id).toBe(vendor.id);
    expect(resubmitted.status).toBe("in_review");

    // Assert: the review queue lists this vendor with exactly one pending extraction, the new w9.
    const queue = await expectStatus<QueueItem[]>(await reviewer.get("/api/review-queue"), 200);
    const item = queue.find((entry) => entry.vendor_id === vendor.id);
    expect(item, "vendor should appear in the review queue").toBeDefined();

    const pending = item!.extractions.filter((e) => e.status === "pending_review");
    expect(pending).toHaveLength(1);
    expect(pending[0].kind).toBe("w9");
    expect(pending[0].document_id).toBe(newW9Doc.id);
  },
);
